// Screen uniforms
uniform float uAspectX;
uniform float uAspectY;
uniform vec2 uAspect;
uniform vec2 uTexSize;
#define texsize vec4(uTexSize, 1.0/uTexSize)

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;
uniform vec4 rand_preset;
uniform vec4 rand_frame;

// Input from vertex shader
in vec2 vUv;
in vec2 vUvOriginal;
in float vRadius;
in float vAngle;

// Output
out vec4 fragColor;

// Textures
uniform sampler2D sampler_main;
uniform sampler2D sampler_noise_lq;
uniform sampler2D sampler_noise_mq;
uniform sampler2D sampler_noise_hq;
uniform sampler2D sampler_blur1;
uniform sampler2D sampler_blur2;
uniform sampler2D sampler_blur3;
#define sampler_fc_main sampler_main
#define sampler_pc_main sampler_main
#define sampler_fw_main sampler_main
#define sampler_pw_main sampler_main
#define sampler_noise_lq_lite sampler_noise_lq
#define sampler_noisevol_lq sampler_noise_lq
#define sampler_noisevol_hq sampler_noise_hq

// MilkDrop q-variable uniforms (q1–q32)
uniform float q1; uniform float q2; uniform float q3; uniform float q4;
uniform float q5; uniform float q6; uniform float q7; uniform float q8;
uniform float q9; uniform float q10; uniform float q11; uniform float q12;
uniform float q13; uniform float q14; uniform float q15; uniform float q16;
uniform float q17; uniform float q18; uniform float q19; uniform float q20;
uniform float q21; uniform float q22; uniform float q23; uniform float q24;
uniform float q25; uniform float q26; uniform float q27; uniform float q28;
uniform float q29; uniform float q30; uniform float q31; uniform float q32;

// MilkDrop _c / _q matrix uniforms
uniform vec4 _c0; uniform vec4 _c1; uniform vec4 _c2; uniform vec4 _c3;
uniform vec4 _c4; uniform vec4 _c5; uniform vec4 _c6; uniform vec4 _c7;
uniform vec4 _c8; uniform vec4 _c9; uniform vec4 _c10; uniform vec4 _c11;
uniform vec4 _c12; uniform vec4 _c13; uniform vec4 _c14;
uniform vec4 _c15; uniform vec4 _c16; uniform vec4 _c17;
uniform vec4 _qa; uniform vec4 _qb; uniform vec4 _qc; uniform vec4 _qd;
uniform vec4 _qe; uniform vec4 _qf; uniform vec4 _qg; uniform vec4 _qh;

// MilkDrop rotation matrices
uniform mat4 rot_s1; uniform mat4 rot_s2; uniform mat4 rot_s3; uniform mat4 rot_s4;
uniform mat4 rot_d1; uniform mat4 rot_d2; uniform mat4 rot_d3; uniform mat4 rot_d4;
uniform mat4 rot_f1; uniform mat4 rot_f2; uniform mat4 rot_f3; uniform mat4 rot_f4;
uniform mat4 rot_vf1; uniform mat4 rot_vf2; uniform mat4 rot_vf3; uniform mat4 rot_vf4;
uniform mat4 rot_uf1; uniform mat4 rot_uf2; uniform mat4 rot_uf3; uniform mat4 rot_uf4;
uniform mat4 rot_rand1; uniform mat4 rot_rand2; uniform mat4 rot_rand3; uniform mat4 rot_rand4;

float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }
float lum(vec3 x) { return dot(x, vec3(0.32, 0.49, 0.29)); }
float lum(vec4 x) { return dot(x.rgb, vec3(0.32, 0.49, 0.29)); }
float sat(float x) { return clamp(x, 0.0, 1.0); }
vec2 sat(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 sat(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 sat(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
//changes: MinDist using float4s, pix now constant
//res & res2 replaced by 255 and 64. Simplified "shadow" code
//Dist est. in uv corr now using 1.0 - GetPixel(uv).b instead GetDist
//noise gen changed. Set compxy = 0, ds = 0, tdist = dist; uv = uv_orig
#define sat clamp01
sampler sampler_pw_noise_lq;
float limit, dist, struc, len; vec2 uv0, uv1; vec3 uv2; vec4 box;
const mat3 RotMat = mat3(q20,q21,q22,q23,q24,q25,q26,q27,q28);
const vec2 compxy = vec2(q12,q13) * 0.0;
const vec3 CamPos = vec3(q4,q5,q6);
const float myzoom = q7, tele = q16;
const float sustain = .98 - 2.0 * q14, ds = 0.0 * q10, tic8 = 1.0/255, ffac = q17;
const vec2 lpos = vec2 (q1,q2);
const mat4 tab1 = .3*mat4 ( 0.0 , 2.0 , 1.0 ,-4, 3.0 , 0.0 , 1.0 , 5.0 , 1.0 ,-3, 2.0 ,-4,  -4, 1.0 , 2.0 , 0.0 ) ;
float aTan2(float y, float x) {float angle;	 float abs_y = abs(y);
if (x >= 0) {float r = (x - abs_y) / (x + abs_y); angle = 1.0 - r;}
else {float r = (x + abs_y) / (abs_y - x); angle = 3.0 - r; }
angle = angle * M_PI/4.0;
return y < 0 ? -angle : angle;}
vec2 GP (vec2 uvi) {return texture(sampler_pc_main, uvi).gb;}
vec2 fstep2 (vec2 xy) {return 0.0039216*round(255.0*xy);}
vec4 fstep4 (vec4 xy) {return round(255.0*xy);}
float GetDist(vec2 uvi) {vec2 tmp; tmp = fstep2(texture(sampler_pc_main, uvi).gb);
return 1.0078125-tmp.y -0.015625*tmp.x;} // = 1.0 - (tmp.y + 1.0/res2*(tmp.x-.50));}
vec2 PutDist(float x) {float tmp; x = 1.0 - x; tmp = fstep2(x);
return (vec2(64.0*(x-tmp)+.495,tmp));}
float tdist (float d) {return d + pow(d, 5.0 ) * 0.0;}
float MinDist (vec2 uvi)
{  float tmp; vec4 na; vec4 nb; vec4 nc; vec4 nd; vec2 pix;
pix = (vec2(1.0)/uTexSize);
na = fstep4(vec4(GP(uvi+pix*vec2( 0.0 , 1.0 )),  GP(uvi+pix*vec2(-1, 0.0 ))));
nb = fstep4(vec4(GP(uvi+pix*vec2(-1,-1)),GP(uvi+pix*vec2( 1.0 ,-1))));
nc = fstep4(vec4(GP(uvi+pix*vec2( 1.0 , 1.0 )),  GP(uvi+pix*vec2(-1, 1.0 ))));
nd = fstep4(vec4(GP(uvi+pix*vec2( 0.0 ,-1)), GP(uvi+pix*vec2( 1.0 , 0.0 ))));
//Eo.S. more efficient usage of min to get min value of all 8 GetDist calls, removes 11ALU
na = vec4 (na.yw + 0.015625*na.xz, nb.yw + 0.015625*nb.xz);
nb = vec4 (nc.yw + 0.015625*nc.xz, nd.yw + 0.015625*nd.xz);
na    = max(na,nb);
na.xy = max(na.xy,na.zw);
return 1.0078125 -  max(na.x, na.y)*0.0039216;}
vec3 Get1 (vec2 uvi) {return mix(GetPixel(uvi), GetBlur1(uvi), 0.0);}
vec3 mbox (vec3 uvi) {vec3 zz, zz0, zzlo; vec2 uv3; float tmp, ang1, len, mod1;
uv3 = floor(uvi.xy+63.99);
mod1 = tab1[uv3.x%4][uv3.y%4];
uvi.xy = 1.0 - abs( fract((uvi.xy-.5) * 0.5 ) * 2.0 - 1.0 ); // Eo.S. mirror code
ang1 = aTan2(uvi.y,uvi.x); len = length(uvi.xy)*7.5;
uvi.z -= mod1;
len *= 1-.3*floor(12.0 * uvi.z*mod1+q19);
zz = vec3 (len, ang1, uvi.z);
zz0 = zz;
for (int n = 0; n <= 7; n++) {
zz = 2.0*clamp(zz,-1, 1.0 )-zz;  tmp = dot(zz,zz);
zz *= clamp01(max(.25/tmp, .25)) * 4.0;
zz = ffac*zz + zz0; if (n == 5) {zzlo = zz;}}
return vec3(length(zzlo), length(zz), (ang1-mod1-fract(zz.y*.0001))*.3);}
shader_body {uv0 = uv_orig; uv = uv_orig;
uv1 = (uv0-.5)*uAspect.xy*tele;
vec3 noise = (texture(sampler_pw_noise_lq,uv*uTexSize.xy*texsize_noise_lq.zw+rand_frame.yz));
vec3 noiseBiased = noise - 0.5;
bool seed = (noise.g < .2);
if (seed) {dist = noise.r;} else {dist = MinDist(uv) + 0.0013 * (noiseBiased.x);}
dist = min(dist,GetDist(uv));
limit = 15 + 15.0 * dist;
uv2 = multiply(vec3(uv1*tdist(dist),tdist(dist))/myzoom,RotMat)+CamPos;
vec3 box = mbox(uv2);
len = mix(box.y,box.x,dist);
struc = sat((-limit+box.y)*.02+1 + box.z) ;
vec2 uv3 =  (uv + .1*(lpos-.5) );
struc -=  (GetDist(uv) > 1.1-GetBlur1(uv3).b)*.5;
float sus = sustain; if (seed) {sus = 1;}
vec3 inside  = vec3 (mix(sat(struc),Get1(uv).r,sus), PutDist(dist));
vec3 outside = Get1(uv)*sus-tic8;
ret = mix(inside,outside,clamp01(len-limit) );
ret.r += noiseBiased.x*-.02;
}
//This is Martin's code

