// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
#define sat clamp01
sampler sampler_pw_noise_lq;
float cloud, tmp, dist, bdist, z;
vec2 dz, uv1, uv2, uv3;
vec3 struc;
const float up = q3;
const float gvol = q8;
const vec3 skycol = vec3 (.4,.5, 1.0 ) / 3.0*(2.0 - gvol);
const vec2 lpos = vec2 (q1,q2), fpos = vec2 (q10,q11);
vec3 lavcol (float t) {return clamp01(pow(t,vec3( 1.0 ,1.8, 4.0 )));}
vec2 noise4 (vec2 uvi) { vec2 n1,n2,n3, zv; zv = 0.00;
n1 = texture(sampler_noise_hq, (uvi));
n2 = texture(sampler_noise_hq, (uvi * 2.0+zv));
//  n3 = texture(sampler_noise_hq, (uvi * 4.0+zv));
return n1 + 1.0*n2 / 2.0  ;}
float flash0 = sat(audioLowSmooth - 1.0);
vec3 flash = flash0/length(uv.xy-cloud*.2-fpos)*(1.0 - cloud)*vec3( 0.0 ,0.3,.6);
vec3 sky = (1.0 - cloud)*skycol+ flash;
uv3 = uv*vec2( 6.0 , 3.0 );
sky *= sat(16.0 * GetBlur1(fract(uv3+floor(uv3.x)*.3)).r - 64.0*(uv1.y+.1));//background
sky *= sat(bdist * 16.0-15) ;
struc = mix(gvol*lavcol(struc0),struc0,bdist)*(1.2-bdist) * sat(1.25-length(uv-lpos));
