float aTan2(float y, float x) {float angle;	 float abs_y = abs(y);
if (x >= 0) {float r = (x - abs_y) / (x + abs_y); angle = 1.0 - r;}
else {float r = (x + abs_y) / (abs_y - x); angle = 3.0 - r; }
angle = angle * M_PI/4.0;
return y < 0 ? -angle : angle;}
vec2 GP (vec2 uvi) {return texture(sampler_pc_main, uvi).gb;}
vec2 fstep2 (vec2 xy) {return 0.0039216*round(255.0*xy);}
vec4 fstep4 (vec4 xy) {return round(255.0*xy);}
float GetDist(vec2 uvi) {vec2 tmp; tmp = fstep2(texture(sampler_pc_main, uvi).gb);
return 1.0078125-tmp.y -0.015625*tmp.x;} // = 1.0 - (tmp.y + 1.0/res2*(tmp.x-.50));}
vec2 PutDist(float x) {float tmp; x = 1.0 - x; tmp = fstep2(x);
return (vec2(64.0*(x-tmp)+.495,tmp));}
float tdist (float d) {return d + pow(d, 5.0 ) * 0.0;}
float MinDist (vec2 uvi)
{  float tmp; vec4 na; vec4 nb; vec4 nc; vec4 nd; vec2 pix;
pix = (vec2(1.0)/uTexSize);
na = fstep4(vec4(GP(uvi+pix*vec2( 0.0 , 1.0 )),  GP(uvi+pix*vec2(-1, 0.0 ))));
nb = fstep4(vec4(GP(uvi+pix*vec2(-1,-1)),GP(uvi+pix*vec2( 1.0 ,-1))));
nc = fstep4(vec4(GP(uvi+pix*vec2( 1.0 , 1.0 )),  GP(uvi+pix*vec2(-1, 1.0 ))));
nd = fstep4(vec4(GP(uvi+pix*vec2( 0.0 ,-1)), GP(uvi+pix*vec2( 1.0 , 0.0 ))));
//Eo.S. more efficient usage of min to get min value of all 8 GetDist calls, removes 11ALU
na = vec4 (na.yw + 0.015625*na.xz, nb.yw + 0.015625*nb.xz);
nb = vec4 (nc.yw + 0.015625*nc.xz, nd.yw + 0.015625*nd.xz);
na    = max(na,nb);
na.xy = max(na.xy,na.zw);
return 1.0078125 -  max(na.x, na.y)*0.0039216;}
vec3 Get1 (vec2 uvi) {return mix(GetPixel(uvi), GetBlur1(uvi), 0.0);}
vec3 mbox (vec3 uvi) {vec3 zz, zz0, zzlo; vec2 uv3; float tmp, ang1, len, mod1;
uv3 = floor(uvi.xy+63.99);
mod1 = tab1[uv3.x%4][uv3.y%4];
uvi.xy = 1.0 - abs( fract((uvi.xy-.5) * 0.5 ) * 2.0 - 1.0 ); // Eo.S. mirror code
ang1 = aTan2(uvi.y,uvi.x); len = length(uvi.xy)*7.5;
uvi.z -= mod1;
len *= 1-.3*floor(12.0 * uvi.z*mod1+q19);
zz = vec3 (len, ang1, uvi.z);
zz0 = zz;
for (int n = 0; n <= 7; n++) {
zz = 2.0*clamp(zz,-1, 1.0 )-zz;  tmp = dot(zz,zz);
zz *= clamp01(max(.25/tmp, .25)) * 4.0;
zz = ffac*zz + zz0; if (n == 5) {zzlo = zz;}}
return vec3(length(zzlo), length(zz), (ang1-mod1-fract(zz.y*.0001))*.3);}
shader_body {uv0 = uv_orig; uv = uv_orig;
uv1 = (uv0-.5)*uAspect.xy*tele;
vec3 noise = (texture(sampler_pw_noise_lq,uv*uTexSize.xy*texsize_noise_lq.zw+rand_frame.yz));
vec3 noiseBiased = noise - 0.5;
bool seed = (noise.g < .2);
if (seed) {dist = noise.r;} else {dist = MinDist(uv) + 0.0013 * (noiseBiased.x);}
dist = min(dist,GetDist(uv));
limit = 15 + 15.0 * dist;
uv2 = multiply(vec3(uv1*tdist(dist),tdist(dist))/myzoom,RotMat)+CamPos;
vec3 box = mbox(uv2);
len = mix(box.y,box.x,dist);
struc = sat((-limit+box.y)*.02+1 + box.z) ;
vec2 uv3 =  (uv + .1*(lpos-.5) );
struc -=  (GetDist(uv) > 1.1-GetBlur1(uv3).b)*.5;
float sus = sustain; if (seed) {sus = 1;}
vec3 inside  = vec3 (mix(sat(struc),Get1(uv).r,sus), PutDist(dist));
vec3 outside = Get1(uv)*sus-tic8;
ret = mix(inside,outside,clamp01(len-limit) );
ret.r += noiseBiased.x*-.02;
}
